// Function to generate currency report for names
function currencyReport(ledger, names, code, rates) {
  return names.map(name => {
    const balance = ledger.balance(name);
    const balanceCents = Math.round(balance * 100);
    const convertedCents = convertMoney(balanceCents, 'USD', code, rates);
    return `${name}: ${formatMoney(convertedCents)}`;
  });
}

// Export the functions
module.exports = {
  balancesReport,
  totalReport,
  interestPreview,
  evenSplit,
  historyReport,
  taxReport,
  convertBalances,
  currencyReport
};

